long long lgput(long long a, long long b) {
    long long res = 1, mod = 1000000007;
    a %= mod;
    while (b > 0) {
        if (b & 1) res = (res * a) % mod;
        a = (a * a) % mod;
        b >>= 1;
    }
    return res;
}
int main() {
