#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
const int INF = 1e9;
int main() {
    int n, S; cin >> n >> S;
    vector<int> c(n), dp(S + 1, INF);
    for(int i = 0; i < n; i++) cin >> c[i];
    dp[0] = 0;
    for(int i = 1; i <= S; i++)
        for(int coin : c)
            if(i >= coin) dp[i] = min(dp[i], dp[i - coin] + 1);
    cout << (dp[S] >= INF ? -1 : dp[S]);
    return 0;
}
